72: // Collapse the static mansion into a handful of draw calls. This is the
73: // difference between a playable phone game and a slideshow.
74: function mergeStaticScene(root) {
75:   root.updateMatrixWorld(true);
76:   const buckets = new Map();
77:   const remove = [];
78:   const AXES = new Set(['position', 'normal', 'uv']);
79: 
80:   function normalizeGeometry(src, matrix) {
81:     const g = src.index ? src.toNonIndexed() : src.clone();
82:     for (const name of Object.keys(g.attributes)) {
83:       if (!AXES.has(name)) g.deleteAttribute(name);
84:     }
85:     if (!g.attributes.normal) g.computeVertexNormals();
86:     if (!g.attributes.uv) {
87:       const count = g.attributes.position.count;
88:       g.setAttribute('uv', new THREE.Float32BufferAttribute(new Float32Array(count * 2), 2));
89:     }
90:     g.applyMatrix4(matrix);
91:     return g;
92:   }
93: 
94:   function walk(obj, dynamicParent) {
95:     const dynamic = dynamicParent || obj.userData.dynamic;
96:     if (dynamic) return;
97:     if (obj.isMesh && !obj.isSkinnedMesh && obj.geometry && !Array.isArray(obj.material)) {
98:       const m = obj.material;
99:       if (!m.transparent && m.opacity >= 0.999 && !m.isShaderMaterial && !obj.userData.noMerge) {
100:         const geo = normalizeGeometry(obj.geometry, obj.matrixWorld);
101:         if (!buckets.has(m.uuid)) buckets.set(m.uuid, { material: m, geometries: [] });
102:         buckets.get(m.uuid).geometries.push(geo);
103:         remove.push(obj);
104:       }
105:     }
106:     for (const child of obj.children) walk(child, dynamic);
107:   }
108:   walk(root, false);
109: 
110:   for (const { material, geometries } of buckets.values()) {
111:     if (geometries.length === 0) continue;
112:     const merged = geometries.length === 1 ? geometries[0] : mergeGeometries(geometries, false);
113:     if (!merged) continue;
114:     const mesh = new THREE.Mesh(merged, material);
115:     mesh.receiveShadow = true;
116:     mesh.matrixAutoUpdate = false;
117:     root.add(mesh);
118:   }
119:   for (const mesh of remove) {
120:     if (mesh.parent) mesh.parent.remove(mesh);
121:     mesh.geometry.dispose();
122:   }
123: }
