653: // ── interaction ──────────────────────────────────────────────
654: function findNearestInteraction() {
655:   if (player.hidden) {
656:     return { type: 'unhide', dist: 0, label: 'LEAVE HIDING SPOT' };
657:   }
658:   let best = null;
659:   for (const c of candles) {
660:     if (c.taken) continue;
661:     const d = Math.hypot(c.pos.x - player.pos.x, c.pos.z - player.pos.z);
662:     if (d < 1.95 && (!best || d < best.dist)) {
663:       best = { type: 'candle', target: c, dist: d, label: 'TAKE THE BLACK CANDLE' };
664:     }
665:   }
666:   for (const h of world.hideSpots) {
667:     const d = h.frontPos.distanceTo(tmpV.set(player.pos.x, 0, player.pos.z));
668:     if (d < 1.5 && (!best || d < best.dist)) {
669:       best = { type: 'hide', target: h, dist: d, label: 'HIDE IN THE WARDROBE' };
670:     }
671:   }
672:   const exitDist = Math.hypot(player.pos.x, player.pos.z - 13.45);
673:   if (exitDist < 2.7 && (!best || exitDist < best.dist)) {
674:     best = {
675:       type: 'exit', dist: exitDist,
676:       label: relics >= 3 ? 'ESCAPE THROUGH THE DOOR' : `THE SEAL HOLDS · ${3 - relics} CANDLE${relics === 2 ? '' : 'S'} REMAIN`
677:     };
678:   }
679:   return best;
680: }
