578: function spawnCandles() {
579:   removeCandles();
580:   const byRoom = {};
581:   for (const spot of world.candleSpots) {
582:     if (!byRoom[spot.room]) byRoom[spot.room] = [];
583:     byRoom[spot.room].push(spot);
584:   }
585:   const roomNames = Object.keys(byRoom);
586:   shuffle(roomNames);
587:   const chosenRooms = roomNames.slice(0, 3);
588:   for (const room of chosenRooms) {
589:     const spots = byRoom[room];
590:     const spot = spots[Math.floor(Math.random() * spots.length)];
591:     candles.push(createCandle(spot));
592:   }
593: }
