595: function createCandle(spot) {
596:   const group = new THREE.Group();
597:   group.position.set(spot.x, 0, spot.z);
598:   const pedestal = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.34, 0.62, 10), stoneCandleMat);
599:   pedestal.position.y = 0.31;
600:   group.add(pedestal);
601:   const rune = new THREE.Mesh(new THREE.TorusGeometry(0.31, 0.014, 6, 22), candleRuneMat);
602:   rune.rotation.x = Math.PI / 2;
603:   rune.position.y = 0.035;
604:   group.add(rune);
605:   const wax = new THREE.Mesh(new THREE.CylinderGeometry(0.065, 0.085, 0.56, 8), candleWaxMat);
606:   wax.position.y = 0.9;
607:   group.add(wax);
608:   const drip = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.05, 0.16, 6), candleWaxMat);
609:   drip.position.set(0.06, 0.75, 0.02);
610:   group.add(drip);
611:   const flame = new THREE.Mesh(new THREE.SphereGeometry(0.036, 8, 8), candleFlameMat);
612:   flame.scale.set(0.8, 2.2, 0.8);
613:   flame.position.y = 1.21;
614:   group.add(flame);
615: 
616:   const halo = new THREE.Sprite(new THREE.SpriteMaterial({
617:     map: candleGlowTex, color: 0xffffff, transparent: true, opacity: 0.55,
618:     blending: THREE.AdditiveBlending, depthWrite: false
619:   }));
620:   halo.position.y = 1.21;
621:   halo.scale.set(1.0, 1.0, 1);
622:   group.add(halo);
623: 
624:   const light = new THREE.PointLight(0x8fe8df, 4.5, 5, 1.8);
625:   light.position.y = 1.15;
626:   group.add(light);
627: 
628:   scene.add(group);
629:   return {
630:     group, light, halo, flame, pos: new THREE.Vector3(spot.x, 0, spot.z),
631:     room: spot.room, taken: false, phase: Math.random() * 10
632:   };
