793: // ── movement + collision ─────────────────────────────────────
794: function getMoveVector() {
795:   let x = 0, y = 0;
796:   if (input.keys.has('KeyW') || input.keys.has('ArrowUp')) y += 1;
797:   if (input.keys.has('KeyS') || input.keys.has('ArrowDown')) y -= 1;
798:   if (input.keys.has('KeyA') || input.keys.has('ArrowLeft')) x -= 1;
799:   if (input.keys.has('KeyD') || input.keys.has('ArrowRight')) x += 1;
800:   if (input.joyMag > 0.08) {
801:     x += input.joyX;
802:     y += input.joyY;
803:   }
804:   const len = Math.hypot(x, y);
805:   if (len > 1) { x /= len; y /= len; }
806:   return { x, y, len: Math.min(1, len) };
807: }
808: 
809: function movePlayer(dt) {
810:   const mv = getMoveVector();
811:   player.moving = mv.len > 0.05;
812: 
813:   const wantsSprint = (input.keys.has('ShiftLeft') || input.keys.has('ShiftRight') || input.sprintHeld) && player.moving;
814:   player.sprinting = wantsSprint && player.stamina > 3;
815: 
816:   if (player.sprinting) player.stamina = Math.max(0, player.stamina - dt * 24);
817:   else player.stamina = Math.min(100, player.stamina + dt * 16);
818: 
819:   const speed = player.sprinting ? 4.55 : 2.75;
820:   const targetVX = (mv.x * speed);
821:   const targetVZ = (-mv.y * speed);
822:   // forward is -z with yaw = 0, so rotate the input by yaw
823:   const cos = Math.cos(player.yaw), sin = Math.sin(player.yaw);
824:   const worldX = targetVX * cos + targetVZ * sin;
825:   const worldZ = -targetVX * sin + targetVZ * cos;
826: 
827:   const accel = player.moving ? 11 : 14;
828:   player.vel.x = lerp(player.vel.x, worldX, Math.min(1, dt * accel));
829:   player.vel.y = lerp(player.vel.y, worldZ, Math.min(1, dt * accel));
830: 
831:   if (!player.moving) {
832:     player.vel.x = lerp(player.vel.x, 0, Math.min(1, dt * 12));
833:     player.vel.y = lerp(player.vel.y, 0, Math.min(1, dt * 12));
834:   }
835: 
836:   const dx = player.vel.x * dt;
837:   const dz = player.vel.y * dt;
838:   const prevX = player.pos.x, prevZ = player.pos.z;
839:   moveAxis('x', dx);
840:   moveAxis('z', dz);
841:   player.pos.x = clamp(player.pos.x, -15.55, 15.55);
842:   player.pos.z = clamp(player.pos.z, -13.55, 16.6);
843: 
844:   const moved = Math.hypot(player.pos.x - prevX, player.pos.z - prevZ);
845: 
846:   if (moved > 0.001) {
847:     player.stepDist += moved;
848:     const stride = player.sprinting ? 1.85 : 2.2;
849:     if (player.stepDist > stride) {
850:       player.stepDist = 0;
851:       audio.step(player.sprinting);
852:       player.bob += Math.PI;
853:     }
854:   }
855: 
856:   // head bob
857:   const speedNorm = Math.min(1, Math.hypot(player.vel.x, player.vel.y) / 4.55);
858:   player.bob += dt * (player.sprinting ? 11 : 7.5) * speedNorm;
859:   const bobAmp = player.sprinting ? 0.055 : 0.033;
860:   player.bobRoll = Math.cos(player.bob * 0.5) * 0.006 * speedNorm;
861:   player.camY = player.eye + Math.sin(player.bob) * bobAmp * speedNorm;
862: 
863:   // stamina UI
864:   staminaBar.style.width = `${player.stamina}%`;
865:   staminaBar.style.background = player.stamina < 24
866:     ? 'linear-gradient(90deg,#5c1a1a,#a43a3a)'
867:     : 'linear-gradient(90deg,#66542f,#c9a86a)';
868:   sprintBtn.classList.toggle('on', player.sprinting);
869: }
870: 
871: function moveAxis(axis, amount) {
872:   if (Math.abs(amount) < 0.000001) return;
873:   const p = player.pos;
874:   const r = player.radius;
875:   if (axis === 'x') p.x += amount; else p.z += amount;
876:   for (const c of world.colliders) {
877:     if (!c.enabled) continue;
878:     if (p.x > c.minX - r && p.x < c.maxX + r && p.z > c.minZ - r && p.z < c.maxZ + r) {
879:       if (axis === 'x') {
880:         p.x = amount > 0 ? c.minX - r - 0.001 : c.maxX + r + 0.001;
881:       } else {
882:         p.z = amount > 0 ? c.minZ - r - 0.001 : c.maxZ + r + 0.001;
883:       }
884:     }
885:   }
886: }
