961: function getDanger() {
962:   if (!ghost.active) return 0;
963:   const d = Math.hypot(player.pos.x - ghost.position.x, player.pos.z - ghost.position.z);
964:   let danger = clamp(1 - d / 13, 0, 1);
965:   if (ghost.state === 'chase') danger = Math.max(danger, 0.55);
966:   if (ghost.state === 'search') danger = Math.max(danger, 0.35);
967:   if (player.hidden) danger *= 0.6;
968:   return danger;
969: }
