973: function spawnBurst(x, y, z, color) {
974:   const mat = new THREE.SpriteMaterial({
975:     map: candleGlowTex, color, transparent: true, opacity: 0.95,
976:     blending: THREE.AdditiveBlending, depthWrite: false
977:   });
978:   const s = new THREE.Sprite(mat);
