682: function useAction() {
683:   if (state !== 'playing') return;
684:   audio.init();
685:   if (player.hidden) { exitHide(); return; }
686:   const target = nearestInteract;
687:   if (!target) return;
688:   if (target.type === 'candle') collectCandle(target.target);
689:   else if (target.type === 'hide') enterHide(target.target);
690:   else if (target.type === 'exit') {
691:     if (relics >= 3) {
692:       showSubtitle('Go. NOW.', 1800);
693:       audio.doorOpen();
694:     } else {
695:       audio.doorLocked();
696:       showSubtitle(`The seal holds. ${3 - relics} black candle${relics === 2 ? '' : 's'} still burn.`, 3400);
697:       flashDamage(0.18, 220);
698:     }
699:   }
700: }
