712: 
713:   if (relics < 3) {
714:     ghost.awaken(player.pos, relics - 1);
715:     const lines = [
716:       'One candle taken. The house exhales.',
717:       'Two candles. Something moves in the walls.',
718:       'The seal tightens around your wrist.'
719:     ];
720:     showSubtitle(lines[Math.min(relics - 1, 2)], 3800);
721:     setObjective(`Find the black candles  ·  ${relics} of 3 taken`);
722:     flashDamage(0.22, 260, 'rgba(150,235,225,.3)');
