985: function updateBursts(dt) {
986:   for (let i = bursts.length - 1; i >= 0; i--) {
987:     const b = bursts[i];
988:     b.life += dt;
989:     const t = b.life / b.max;
990:     b.sprite.scale.setScalar(0.4 + t * 4.5);
991:     b.sprite.material.opacity = Math.max(0, 0.95 * (1 - t));
992:     b.sprite.position.y += dt * 0.5;
993:     if (t >= 1) {
994:       scene.remove(b.sprite);
995:       b.sprite.material.dispose();
996:       bursts.splice(i, 1);
997:     }
998:   }
999: }
