1252: function animate() {
1253:   requestAnimationFrame(animate);
1254:   const rawDt = clock.getDelta();
1255:   const dt = Math.min(rawDt, 0.05);
1256:   const time = performance.now() / 1000;
1257: 
1258:   if (state === 'title') {
1259:     updateTitle(dt, time);
1260:     world.update(dt, camera.position);
1261:     audio.update(dt, 0);
1262:   } else if (state === 'playing') {
1263:     updatePlaying(dt, time);
1264:     world.update(dt, camera.position);
1265:   } else if (state === 'paused') {
1266:     // frozen house, but still rendered
1267:   } else if (state === 'caught') {
1268:     // camera convulses under the scare overlay
1269:     camera.position.x = player.pos.x + (Math.random() - 0.5) * 0.08;
1270:     camera.position.z = player.pos.z + (Math.random() - 0.5) * 0.08;
1271:     camera.rotation.z = (Math.random() - 0.5) * 0.06;
1272:     world.update(dt, camera.position);
1273:   } else {
1274:     world.update(dt, camera.position);
1275:   }
1276: 
1277:   // Adaptive resolution keeps the frame rate usable on weaker phones.
1278:   qualityFrames++;
1279:   qualityElapsed += rawDt;
1280:   if (qualityElapsed > 2.2) {
1281:     const fps = qualityFrames / qualityElapsed;
1282:     if (fps < 28 && renderScale > 0.58) {
1283:       renderScale = Math.max(0.58, renderScale - 0.14);
1284:       renderer.setPixelRatio(MAX_PR * renderScale);
