1047:   let blackoutTimer = 0;
1048:   let elapsed = 0;
1049: 
1050:   return {
1051:     colliders,
1052:     hideSpots,
1053:     candleSpots: CANDLE_SPOTS,
1054:     rooms: ROOM_DEFS,
1055:     exit,
1056:     lights,
1057:     hemi,
1058:     dust,
1059:     dustSeed,
1060:     get position() { return new THREE.Vector3(0, 0, 0); },
1061:     triggerBlackout(seconds = 1.4) { blackoutTimer = seconds; },
1062:     roomAt(x, z) {
1063:       for (const r of ROOM_DEFS) {
1064:         if (x >= r.minX && x <= r.maxX && z >= r.minZ && z <= r.maxZ) return r;
1065:       }
1066:       return null;
1067:     },
1068:     update(dt, cameraPos) {
1069:       elapsed += dt;
1070:       blackoutTimer = Math.max(0, blackoutTimer - dt);
1071:       const blackout = blackoutTimer > 0;
1072:       for (const f of flickerLights) {
1073:         const t = elapsed * f.speed + f.phase;
1074:         let k = 0.86 + Math.sin(t) * 0.08 + Math.sin(t * 2.7 + 1.3) * 0.045;
1075:         if (blackout) k *= (Math.random() > 0.45 ? 0.02 : 1.1);
1076:         else if (Math.random() < 0.0016) k *= 0.35;
1077:         f.light.intensity = f.base * k;
1078:       }
1079:       for (const fire of fires) {
1080:         const flick = 0.82 + Math.sin(elapsed * 13 + fire.phase) * 0.12 + Math.random() * 0.1;
1081:         fire.light.intensity = fire.base * flick;
1082:         fire.sprites.forEach((s, i) => {
1083:           const p = flick + Math.sin(elapsed * (9 + i * 3.2) + fire.phase + i) * 0.12;
1084:           s.scale.set(s.userData.baseX * (0.88 + p * 0.16), s.userData.baseY * (0.82 + p * 0.22), 1);
1085:           s.material.opacity = s.userData.baseOp * (0.82 + p * 0.18);
1086:           s.position.x = Math.sin(elapsed * (2.4 + i) + fire.phase) * 0.04;
1087:         });
1088:       }
1089:       // dust drifts toward the player, slowly
1090:       if (cameraPos) {
