482:     ctx.moveTo(x, y);
483:     ctx.bezierCurveTo(x + 10, y + 12, x - 8, y + 24, x + 6, y + 38);
484:     ctx.stroke();
485:   }
486: 
487:   // face edge shading
488:   const edge = ctx.createRadialGradient(256, 360, 120, 256, 360, 270);
489:   edge.addColorStop(0, 'rgba(0,0,0,0)');
490:   edge.addColorStop(0.8, 'rgba(0,0,0,.28)');
491:   edge.addColorStop(1, 'rgba(0,0,0,.6)');
492:   ctx.fillStyle = edge;
493:   ctx.fillRect(0, 0, W, H);
494: 
495:   ctx.restore();
496: 
497:   // lank hair over the face — irregular, heavier at the temples
498:   for (let i = 0; i < 22; i++) {
499:     const side = i % 3 === 0 ? (Math.random() > 0.5 ? 1 : -1) : 0;
500:     let x = side ? (side > 0 ? 355 + Math.random() * 80 : 50 + Math.random() * 90) : 120 + Math.random() * 272;
501:     let y = 55 + Math.random() * 90;
502:     const sway = 12 + Math.random() * 34;
503:     ctx.strokeStyle = `rgba(3,5,4,${0.42 + Math.random() * 0.5})`;
504:     ctx.lineWidth = 1 + Math.random() * 6;
505:     ctx.beginPath();
506:     ctx.moveTo(x, y);
507:     for (let seg = 0; seg < 5; seg++) {
508:       const nx = x + (Math.random() - 0.5) * sway * 2 + (x < 256 ? -6 : 6);
509:       const ny = y + 70 + Math.random() * 60;
510:       ctx.quadraticCurveTo(x + (Math.random() - 0.5) * sway * 2, (y + ny) / 2, nx, ny);
511:       x = nx; y = ny;
512:       if (y > 690) break;
513:     }
514:     ctx.stroke();
515:   }
516:   // clumps of hair spilling over the cheeks
517:   ctx.fillStyle = 'rgba(3,5,4,.82)';
518:   for (const sx of [-1, 1]) {
519:     ctx.beginPath();
520:     ctx.moveTo(256 + sx * 128, 90);
521:     ctx.bezierCurveTo(256 + sx * 165, 220, 256 + sx * 150, 400, 256 + sx * 118, 566);
522:     ctx.bezierCurveTo(256 + sx * 150, 430, 256 + sx * 120, 250, 256 + sx * 100, 150);
523:     ctx.closePath();
524:     ctx.fill();
525:   }
526: 
527:   // final grime and film grain
528:   for (let i = 0; i < 900; i++) {
529:     const x = Math.random() * W, y = Math.random() * H;
530:     ctx.fillStyle = Math.random() > 0.5 ? `rgba(255,255,255,${Math.random() * 0.035})` : `rgba(0,0,0,${Math.random() * 0.07})`;
531:     ctx.fillRect(x, y, 1 + Math.random() * 2, 1 + Math.random() * 2);
532:   }
533:   const vig = ctx.createRadialGradient(256, 380, 130, 256, 380, 430);
534:   vig.addColorStop(0, 'rgba(0,0,0,0)');
535:   vig.addColorStop(1, 'rgba(0,0,0,.62)');
536:   ctx.fillStyle = vig;
537:   ctx.fillRect(0, 0, W, H);
538: }
