905: // ── compass / HUD ────────────────────────────────────────────
906: function updateHUD() {
907:   let target = null;
908:   let label = 'CANDLE';
909:   if (relics >= 3) {
910:     target = tmpV.set(0, 0, 14.4);
911:     label = 'EXIT';
912:   } else {
913:     let best = Infinity;
914:     for (const c of candles) {
915:       if (c.taken) continue;
916:       const d = Math.hypot(c.pos.x - player.pos.x, c.pos.z - player.pos.z);
917:       if (d < best) { best = d; target = tmpV.set(c.pos.x, 0, c.pos.z); }
918:     }
919:   }
920:   if (target) {
921:     const dx = target.x - player.pos.x;
922:     const dz = target.z - player.pos.z;
923:     const cos = Math.cos(player.yaw), sin = Math.sin(player.yaw);
924:     const right = dx * cos - dz * sin;
925:     const fwd = -dx * sin - dz * cos;
926:     const angle = Math.atan2(right, fwd) * 180 / Math.PI;
927:     compassArrow.style.transform = `rotate(${angle}deg)`;
928:     compassDist.textContent = `${Math.max(1, Math.round(Math.hypot(dx, dz)))}m`;
929:     compassLabel.textContent = label;
930:     compassDist.style.color = label === 'EXIT' ? '#9fd6cf' : '#c9b78e';
931:   }
932:   compassLabel.style.color = label === 'EXIT' ? '#78b6ae' : '#8d8169';
933: 
934:   const danger = getDanger();
935:   dangerVignette.style.opacity = String(danger * 0.92);
936:   dangerVignette.style.background = ghost.state === 'chase'
937:     ? 'radial-gradient(ellipse at 50% 50%, transparent 34%, rgba(120,4,8,.55) 82%, rgba(60,0,2,.9) 100%)'
938:     : 'radial-gradient(ellipse at 50% 50%, transparent 40%, rgba(70,10,14,.42) 85%, rgba(30,0,2,.8) 100%)';
939: 
940:   nearestInteract = findNearestInteraction();
941:   if (nearestInteract) {
942:     interactPrompt.classList.remove('hidden');
943:     interactText.textContent = nearestInteract.label;
944:     interactKey.textContent = isTouch ? '✦' : 'E';
945:     crosshair.classList.add('active');
946:     useBtn.classList.add('pulse');
947:   } else {
948:     interactPrompt.classList.add('hidden');
949:     crosshair.classList.remove('active');
950:     useBtn.classList.remove('pulse');
951:   }
952: 
953:   // room name toast
954:   const room = world.roomAt(player.pos.x, player.pos.z);
955:   if (room && (!currentRoom || room.id !== currentRoom.id)) {
956:     currentRoom = room;
957:     showToast(room.name);
958:   }
959: }
