60:   const H = WALL_HEIGHT;
61:   const mats = makeMaterials();
62: 
63:   // ── shared helpers ─────────────────────────────────────────
64:   function addCollider(cx, cz, w, d, tag = 'solid') {
65:     const c = {
66:       minX: cx - w / 2, maxX: cx + w / 2,
67:       minZ: cz - d / 2, maxZ: cz + d / 2,
68:       tag, enabled: true
69:     };
70:     colliders.push(c);
71:     return c;
72:   }
73: 
74:   function box(x, y, z, w, h, d, material, opts = {}) {
75:     const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
76:     mesh.position.set(x, y, z);
77:     if (opts.ry) mesh.rotation.y = opts.ry;
78:     mesh.castShadow = !!opts.castShadow;
79:     mesh.receiveShadow = opts.receiveShadow !== false;
80:     scene.add(mesh);
81:     if (opts.collide) {
82:       if (Math.abs(Math.sin(opts.ry || 0)) > 0.7) addCollider(x, z, d, w, opts.tag);
83:       else addCollider(x, z, w, d, opts.tag);
84:     }
85:     return mesh;
86:   }
87: 
88:   function cyl(x, y, z, rTop, rBot, h, material, seg = 10) {
89:     const mesh = new THREE.Mesh(new THREE.CylinderGeometry(rTop, rBot, h, seg), material);
90:     mesh.position.set(x, y, z);
91:     mesh.receiveShadow = true;
92:     scene.add(mesh);
93:     return mesh;
94:   }
95: 
96:   function glow(x, y, z, size, color = '#ffd28a', opacity = 0.7) {
97:     const mat = new THREE.SpriteMaterial({
98:       map: getGlowTexture(color), transparent: true, opacity,
99:       blending: THREE.AdditiveBlending, depthWrite: false, fog: true
100:     });
101:     const s = new THREE.Sprite(mat);
102:     s.position.set(x, y, z);
103:     s.scale.set(size, size, 1);
104:     s.userData.baseOpacity = opacity;
105:     scene.add(s);
106:     glowSprites.push(s);
107:     return s;
108:   }
