127:     const d = r.maxZ - r.minZ;
128:     const wm = mats.wood.clone();
129:     wm.map = mats.wood.map.clone();
130:     wm.map.needsUpdate = true;
131:     wm.map.repeat.set(w / 5.2, d / 5.2);
132:     wm.map.rotation = Math.PI / 2;
133:     wm.color = new THREE.Color(r.id === 'chapel' ? 0x8a9490 : r.id === 'kitchen' ? 0xa8a49a : 0xffffff);
134: 
135:     const floorMat = r.id === 'chapel' ? mats.stoneFloor : r.id === 'kitchen' ? mats.kitchenFloor : wm;
136:     floorMaterials[r.id] = floorMat;
137:     const floor = new THREE.Mesh(new THREE.PlaneGeometry(w, d), floorMat);
138:     floor.rotation.x = -Math.PI / 2;
139:     floor.position.set((r.minX + r.maxX) / 2, 0.015, (r.minZ + r.maxZ) / 2);
