150:   // ── walls ──────────────────────────────────────────────────
151:   const exteriorWalls = [
152:     [-16, 14, -1.22, 14], [1.22, 14, 16, 14],
153:     [-16, -14, 16, -14],
154:     [-16, -14, -16, 14],
155:     [16, -14, 16, 14],
156:   ];
157:   const interiorWalls = [
158:     [-4, -14, -4, -10], [-4, -8, -4, -1], [-4, 1, -4, 8], [-4, 10, -4, 14],
159:     [4, -14, 4, -10], [4, -8, 4, -1], [4, 1, 4, 8], [4, 10, 4, 14],
160:     [-16, -4, -14, -4], [-12, -4, -1, -4], [1, -4, 12, -4], [14, -4, 16, -4],
161:     [-16, 4, -14, 4], [-12, 4, -4, 4], [-4, 4, -1, 4], [1, 4, 4, 4],
162:     [4, 4, 12, 4], [14, 4, 16, 4],
