168:   function addWall(x1, z1, x2, z2, thick, exterior) {
169:     const horizontal = Math.abs(x2 - x1) > Math.abs(z2 - z1);
170:     const length = horizontal ? Math.abs(x2 - x1) : Math.abs(z2 - z1);
171:     if (length < 0.05) return;
172:     const cx = (x1 + x2) / 2, cz = (z1 + z2) / 2;
173: 
174:     const map = mats.wallpaper.map.clone();
175:     map.needsUpdate = true;
176:     map.repeat.set(length / 2.4, H / 2.4);
177:     const wallMat = mats.wallpaper.clone();
178:     wallMat.map = map;
179:     if (exterior) wallMat.color = new THREE.Color(0x879491);
180:     wallMat.side = THREE.FrontSide;
181: 
182:     const geo = new THREE.BoxGeometry(horizontal ? length : thick, H, horizontal ? thick : length);
183:     const mesh = new THREE.Mesh(geo, wallMat);
184:     mesh.position.set(cx, H / 2, cz);
185:     mesh.receiveShadow = true;
186:     scene.add(mesh);
187: 
188:     // dark wainscot around the lower wall
189:     const wain = new THREE.Mesh(
190:       new THREE.BoxGeometry(horizontal ? length + 0.02 : thick + 0.09, 1.1, horizontal ? thick + 0.09 : length + 0.02),
191:       mats.wainscot
192:     );
193:     wain.position.set(cx, 0.56, cz);
194:     wain.receiveShadow = true;
195:     scene.add(wain);
