197:     // baseboard + crown
198:     const base = new THREE.Mesh(
199:       new THREE.BoxGeometry(horizontal ? length + 0.02 : thick + 0.14, 0.11, horizontal ? thick + 0.14 : length + 0.02),
200:       mats.trim
201:     );
202:     base.position.set(cx, 0.055, cz);
203:     scene.add(base);
204: 
205:     const crown = new THREE.Mesh(
206:       new THREE.BoxGeometry(horizontal ? length + 0.02 : thick + 0.12, 0.13, horizontal ? thick + 0.12 : length + 0.02),
207:       mats.trim
208:     );
209:     crown.position.set(cx, H - 0.08, cz);
210:     scene.add(crown);
211: 
212:     addCollider(cx, cz, horizontal ? length + (exterior ? 0.1 : 0.06) : thick, horizontal ? thick : length + (exterior ? 0.1 : 0.06), 'wall');
213:   }
