215:   // ── doorway frames & ajar doors ────────────────────────────
216:   // vertical wall doors: [x, z1, z2]
217:   const vDoors = [
218:     [-4, -10, -8], [-4, -1, 1], [-4, 8, 10],
219:     [4, -10, -8], [4, -1, 1], [4, 8, 10],
220:   ];
221:   // horizontal wall doors: [z, x1, x2]
222:   const hDoors = [
223:     [-4, -14, -12], [-4, -1, 1], [-4, 12, 14],
224:     [4, -14, -12], [4, -1, 1], [4, 12, 14],
225:   ];
