227:   vDoors.forEach(([x, z1, z2], i) => {
228:     addDoorFrame('v', x, z1, z2);
229:     addDoorPanel('v', x, z1, z2, i % 3 === 0 ? 1 : -1);
230:   });
231:   hDoors.forEach(([z, x1, x2], i) => {
232:     addDoorFrame('h', z, x1, x2);
233:     addDoorPanel('h', z, x1, x2, i % 2 === 0 ? 1 : -1);
