236:   function addDoorFrame(axis, fixed, a, b) {
237:     const gap = Math.abs(b - a);
238:     const center = (a + b) / 2;
239:     const post = 0.16;
240:     if (axis === 'v') {
241:       box(fixed, 1.38, a + 0.05, 0.52, 2.76, post, mats.trim);
242:       box(fixed, 1.38, b - 0.05, 0.52, 2.76, post, mats.trim);
243:       box(fixed, 2.78, center, 0.52, 0.22, gap, mats.trim);
244:       box(fixed, 2.9, center, 0.62, 0.1, gap + 0.22, mats.trim);
245:     } else {
246:       box(a + 0.05, 1.38, fixed, post, 2.76, 0.52, mats.trim);
247:       box(b - 0.05, 1.38, fixed, post, 2.76, 0.52, mats.trim);
248:       box(center, 2.78, fixed, gap, 0.22, 0.52, mats.trim);
249:       box(center, 2.9, fixed, gap + 0.22, 0.1, 0.62, mats.trim);
250:     }
251:   }
