253:   function addDoorPanel(axis, fixed, a, b, direction) {
254:     const gap = Math.abs(b - a) - 0.14;
255:     const group = new THREE.Group();
256:     const hingeX = axis === 'h' ? a + 0.07 : fixed;
257:     const hingeZ = axis === 'v' ? a + 0.07 : fixed;
258:     group.position.set(hingeX, 1.36, hingeZ);
259:     const baseAngle = axis === 'v' ? -Math.PI / 2 : 0;
260:     group.rotation.y = baseAngle + direction * (1.72 + Math.random() * 0.22);
261: 
262:     const panel = new THREE.Mesh(new THREE.BoxGeometry(gap, 2.62, 0.075), mats.door);
263:     panel.position.x = gap / 2;
264:     panel.castShadow = true;
265:     group.add(panel);
266: 
267:     // recessed door panels
268:     for (let i = 0; i < 2; i++) {
269:       const inset = new THREE.Mesh(new THREE.BoxGeometry(gap * 0.62, 0.92, 0.035), mats.doorInset);
270:       inset.position.set(gap / 2, i === 0 ? 0.58 : -0.62, 0.05);
271:       group.add(inset);
272:     }
273:     const knob = new THREE.Mesh(new THREE.SphereGeometry(0.055, 8, 8), mats.brass);
274:     knob.position.set(gap * 0.86, 0, 0.09);
275:     group.add(knob);
276:     scene.add(group);
277:   }
