282:   function buildExitDoor() {
283:     box(-1.35, 1.38, 14, 0.2, 2.76, 0.6, mats.trim);
284:     box(1.35, 1.38, 14, 0.2, 2.76, 0.6, mats.trim);
285:     box(0, 2.9, 14, 3.1, 0.2, 0.7, mats.trim);
286:     // wall above the double doors (the doorway gap runs to the ceiling)
287:     box(0, 3.2, 14, 2.9, 0.62, 0.62, mats.wainscot);
288: 
289:     const leftPivot = new THREE.Group();
290:     leftPivot.position.set(-1.2, 1.38, 13.86);
291:     leftPivot.userData.dynamic = true;
292:     const rightPivot = new THREE.Group();
293:     rightPivot.position.set(1.2, 1.38, 13.86);
294:     rightPivot.userData.dynamic = true;
295: 
296:     const makePanel = (w, sign) => {
297:       const g = new THREE.Group();
298:       const p = new THREE.Mesh(new THREE.BoxGeometry(w, 2.72, 0.09), mats.door);
299:       p.position.x = sign * w / 2;
300:       p.castShadow = true;
301:       g.add(p);
302:       for (let i = 0; i < 3; i++) {
303:         const inset = new THREE.Mesh(new THREE.BoxGeometry(w * 0.66, 0.54, 0.035), mats.doorInset);
304:         inset.position.set(sign * w / 2, 0.82 - i * 0.78, 0.055);
305:         g.add(inset);
306:       }
307:       const handle = new THREE.Mesh(new THREE.SphereGeometry(0.06, 8, 8), mats.brass);
308:       handle.position.set(sign * (w - 0.14), 0, 0.1);
309:       g.add(handle);
310:       return g;
311:     };
312:     leftPivot.add(makePanel(1.2, 1));
313:     rightPivot.add(makePanel(1.2, -1));
314: 
315:     // three rune sockets on the left door
316:     const sockets = [];
317:     for (let i = 0; i < 3; i++) {
318:       const ring = new THREE.Mesh(new THREE.TorusGeometry(0.105, 0.022, 8, 18), mats.runeOff);
319:       ring.position.set(0.55 + (i - 1) * 0.3, 1.02, 0.09);
320:       leftPivot.add(ring);
321:       sockets.push(ring);
322:     }
323: 
324:     scene.add(leftPivot, rightPivot);
325: 
326:     const collider = addCollider(0, 13.98, 2.55, 0.36, 'exit');
327: 
328:     const doorGlow = glow(0, 2.1, 13.55, 1.4, '#93c8c3', 0.14);
329: 
330:     return {
331:       leftPivot, rightPivot, sockets, collider, open: false, opening: false, openness: 0,
332:       setOpen(on) {
333:         this.opening = on;
334:         if (on) collider.enabled = false;
335:       },
336:       reset() {
337:         this.open = false; this.opening = false; this.openness = 0;
338:         collider.enabled = true;
339:         leftPivot.rotation.y = 0; rightPivot.rotation.y = 0;
340:         sockets.forEach((s, i) => { s.material = i < 0 ? mats.runeOn : mats.runeOff; });
341:         doorGlow.material.opacity = 0.02;
342:         doorGlow.userData.baseOpacity = 0.02;
343:       },
344:       setLit(n) {
345:         sockets.forEach((s, i) => { s.material = i < n ? mats.runeOn : mats.runeOff; });
346:         doorGlow.material.opacity = 0.02 + n * 0.05;
347:         doorGlow.userData.baseOpacity = 0.02 + n * 0.05;
348:       },
349:       update(dt) {
350:         if (this.opening && this.openness < 1) {
351:           this.openness = Math.min(1, this.openness + dt / 2.3);
352:           const e = easeInOut(this.openness);
353:           leftPivot.rotation.y = e * 1.86;
354:           rightPivot.rotation.y = -e * 1.86;
355:           if (this.openness >= 1) this.open = true;
356:         }
357:         if (this.open) {
358:           doorGlow.material.opacity = 0.35 + Math.sin(performance.now() * 0.003) * 0.1;
359:         }
360:       }
361:     };
362:   }
363: 
364:   function easeInOut(t) { return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2; }
365: 
366:   // porch / outside
367:   const porch = new THREE.Mesh(new THREE.PlaneGeometry(12, 8), mats.porch);
368:   porch.rotation.x = -Math.PI / 2;
