396:   const porchLight = pointLight(0, 3.4, 18.5, 0x87aebc, 16, 16, 1.6);
397:   addFlicker(porchLight, 16, 0.4, 2.2);
398:   box(-2.4, 0.32, 14.65, 0.45, 0.65, 3.6, mats.stone);
399:   box(2.4, 0.32, 14.65, 0.45, 0.65, 3.6, mats.stone);
400:   for (let i = 0; i < 3; i++) {
401:     box(0, 0.08 + i * 0.055, 14.8 + i * 0.32, 3.1 - i * 0.1, 0.11, 0.45, mats.stone);
402:   }
403:   // distant tree silhouettes outside the door
404:   for (let i = 0; i < 8; i++) {
405:     const t = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.26, 5 + Math.random() * 5, 5), mats.bark);
406:     t.position.set(-14 + i * 4 + Math.random() * 2, 2.5, 21 + Math.random() * 6);
407:     scene.add(t);
408:     const crown = new THREE.Mesh(new THREE.IcosahedronGeometry(1.6 + Math.random() * 1.2, 0), mats.foliage);
409:     crown.position.set(t.position.x, t.position.y + 2.4, t.position.z);
410:     crown.scale.y = 1.35;
411:     scene.add(crown);
412:   }
