437:   function windowFrame(x, y, z, ry, w = 2.2, h = 2.9, stained = false) {
438:     const g = new THREE.Group();
439:     g.position.set(x, y, z);
440:     g.rotation.y = ry;
441:     const glass = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial({
442:       map: stained ? stainedGlassTexture() : moonTexture(),
443:       transparent: true, opacity: stained ? 0.85 : 0.75,
444:       color: stained ? 0xffffff : 0x9fb8c4,
445:       blending: THREE.AdditiveBlending, depthWrite: false, fog: true
446:     }));
447:     g.add(glass);
448:     const t = 0.1;
