888: // ── camera ───────────────────────────────────────────────────
889: function updateCamera(dt) {
890:   camera.rotation.y = player.yaw;
891:   camera.rotation.x = player.pitch;
892:   camera.rotation.z = player.bobRoll;
893: 
894:   let shake = 0;
895:   if (ghost.active && !player.hidden) {
896:     const d = Math.hypot(player.pos.x - ghost.position.x, player.pos.z - ghost.position.z);
897:     if (d < 6) shake = (1 - d / 6) * 0.012;
898:     if (ghost.state === 'chase') shake += 0.006;
899:   }
900:   const sx = (Math.random() - 0.5) * shake;
901:   const sy = (Math.random() - 0.5) * shake;
902:   camera.position.set(player.pos.x + sx, (player.camY ?? player.eye) + sy, player.pos.z);
903: }
