541: function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
542: function lerp(a, b, t) { return a + (b - a) * t; }
543: function wrapAngle(a) { while (a > Math.PI) a -= Math.PI * 2; while (a < -Math.PI) a += Math.PI * 2; return a; }
544: function formatTime(ms) {
