572: const candleGlowTex = glowTexture('#9fe8e3');
573: const stoneCandleMat = lambert({ color: 0x3b403d, roughness: 0.92 });
574: const candleWaxMat = lambert({ color: 0x141619, roughness: 0.72, emissive: 0x060708 });
