972: const bursts = [];
973: function spawnBurst(x, y, z, color) {
974:   const mat = new THREE.SpriteMaterial({
975:     map: candleGlowTex, color, transparent: true, opacity: 0.95,
976:     blending: THREE.AdditiveBlending, depthWrite: false
977:   });
978:   const s = new THREE.Sprite(mat);
979:   s.position.set(x, y, z);
980:   s.scale.set(0.4, 0.4, 1);
981:   scene.add(s);
982:   bursts.push({ sprite: s, life: 0, max: 1.2 });
983: }
984: 
985: function updateBursts(dt) {
986:   for (let i = bursts.length - 1; i >= 0; i--) {
987:     const b = bursts[i];
988:     b.life += dt;
989:     const t = b.life / b.max;
990:     b.sprite.scale.setScalar(0.4 + t * 4.5);
991:     b.sprite.material.opacity = Math.max(0, 0.95 * (1 - t));
992:     b.sprite.position.y += dt * 0.5;
993:     if (t >= 1) {
994:       scene.remove(b.sprite);
995:       b.sprite.material.dispose();
996:       bursts.splice(i, 1);
997:     }
998:   }
999: }
