import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(require('fs').readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + require('fs').readFileSync(join(runtime, 'display'), 'utf8').trim();

const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.setDefaultTimeout(20000);
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
page.on('response', r => { if (r.status() >= 400) errors.push(`HTTP ${r.status()} ${r.url()}`); });

await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__hollow);
await page.waitForTimeout(2200);
await page.screenshot({ path: join(out, '01-title.jpg'), type: 'jpeg', quality: 72 });

const info = await page.evaluate(() => ({
  state: __hollow.state,
  candles: __hollow.candles.length,
  rooms: __hollow.world.rooms.length,
  hide: __hollow.world.hideSpots.length,
  canvas: [__hollow.renderer.domElement.width, __hollow.renderer.domElement.height],
  drawCalls: __hollow.renderer.info.render.calls,
  tris: __hollow.renderer.info.render.triangles
}));
console.log('TITLE', JSON.stringify(info));

await page.click('#start-btn');
await page.waitForTimeout(900);
// dismiss intro
await page.keyboard.press('Space');
await page.waitForTimeout(1600);
await page.screenshot({ path: join(out, '02-play.jpg'), type: 'jpeg', quality: 72 });

console.log('START', JSON.stringify(await page.evaluate(() => ({
  state: __hollow.state,
  candles: __hollow.candles.map(c => ({ x: c.pos.x, z: c.pos.z, room: c.room })),
  hudHidden: document.getElementById('hud').classList.contains('hidden'),
  titleHidden: document.getElementById('title-screen').classList.contains('hidden'),
  drawCalls: __hollow.renderer.info.render.calls,
  tris: __hollow.renderer.info.render.triangles
}))));

// Each candle: teleport next to it, let HUD refresh, then use.
for (let i = 0; i < 3; i++) {
  const pick = await page.evaluate((i) => {
    const c = __hollow.candles.find(c => !c.taken);
    __hollow.teleport(c.pos.x + 0.6, c.pos.z);
    return { x: c.pos.x, z: c.pos.z, room: c.room };
  }, i);
  await page.waitForTimeout(350);
  const label = await page.evaluate(() => document.getElementById('interact-text').textContent);
  await page.evaluate(() => __hollow.use());
  await page.waitForTimeout(500);
  const st = await page.evaluate(() => ({ relics: __hollow.relics, state: __hollow.state, ghost: __hollow.ghost.state, active: __hollow.ghost.active }));
  console.log('CANDLE', i, JSON.stringify(pick), 'prompt:', label, '=>', JSON.stringify(st));
}

await page.screenshot({ path: join(out, '03-after-candles.jpg'), type: 'jpeg', quality: 72 });

const door = await page.evaluate(() => ({ open: __hollow.world.exit.open, opening: __hollow.world.exit.opening, openness: __hollow.world.exit.openness, ghost: __hollow.ghost.state, final: __hollow.ghost.final, objective: document.getElementById('objective-text').textContent }));
console.log('DOOR', JSON.stringify(door));

await page.waitForTimeout(1200);
// stand on the threshold and finish
await page.evaluate(() => __hollow.teleport(0, 14.4));
await page.waitForTimeout(600);
console.log('WIN?', JSON.stringify(await page.evaluate(() => ({ state: __hollow.state, openness: __hollow.world.exit.openness, z: __hollow.player.pos.z }))));
await page.waitForTimeout(2200);
await page.screenshot({ path: join(out, '04-win.jpg'), type: 'jpeg', quality: 72 });
console.log('END', JSON.stringify(await page.evaluate(() => ({
  state: __hollow.state,
  visible: !document.getElementById('end-screen').classList.contains('hidden'),
  winClass: document.getElementById('end-screen').classList.contains('win'),
  title: document.getElementById('end-title').textContent,
  stats: document.getElementById('end-stats').textContent.replace(/\s+/g, ' ').trim()
}))));

// restart, then test death
await page.click('#again-btn');
await page.waitForTimeout(900);
console.log('RESTART', JSON.stringify(await page.evaluate(() => ({ state: __hollow.state, relics: __hollow.relics, candles: __hollow.candles.length, ghost: __hollow.ghost.state, active: __hollow.ghost.active }))));
await page.evaluate(() => {
  const p = __hollow.player;
  __hollow.ghost.active = true;
  __hollow.ghost.state = 'chase';
  __hollow.ghost.position.set(p.pos.x, 0, p.pos.z);
  __hollow.ghost.group.position.set(p.pos.x, 0, p.pos.z);
});
await page.waitForTimeout(400);
console.log('CAUGHT', JSON.stringify(await page.evaluate(() => ({ state: __hollow.state, jumpscare: document.getElementById('jumpscare').classList.contains('show') }))));
await page.waitForTimeout(2500);
await page.screenshot({ path: join(out, '05-dead.jpg'), type: 'jpeg', quality: 72 });
console.log('DEAD', JSON.stringify(await page.evaluate(() => ({ state: __hollow.state, visible: !document.getElementById('end-screen').classList.contains('hidden'), title: document.getElementById('end-title').textContent }))));

// mobile
const m = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
m.setDefaultTimeout(20000);
m.on('pageerror', e => errors.push('mobile pageerror: ' + e.message));
await m.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await m.waitForFunction(() => window.__hollow);
await m.waitForTimeout(2200);
await m.screenshot({ path: join(out, '06-mobile-title.jpg'), type: 'jpeg', quality: 72 });
await m.tap('#start-btn');
await m.waitForTimeout(1200);
const mInfo = await m.evaluate(() => ({
  state: __hollow.state,
  touchDisplay: getComputedStyle(document.getElementById('touch-controls')).display,
  joystick: (() => { const r = document.getElementById('joystick-base').getBoundingClientRect(); return [Math.round(r.x), Math.round(r.y), Math.round(r.width)]; })(),
  introHidden: document.getElementById('intro-overlay').classList.contains('hidden'),
  hudHidden: document.getElementById('hud').classList.contains('hidden')
}));
console.log('MOBILE', JSON.stringify(mInfo));
await m.screenshot({ path: join(out, '07-mobile-play.jpg'), type: 'jpeg', quality: 72 });

console.log('ERRORS', JSON.stringify(errors));
await browser.close();

