import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(require('fs').readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + require('fs').readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.setDefaultTimeout(30000);
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', x => { if (x.type() === 'error') errors.push('console: ' + x.text()); });
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__hollow);
await page.waitForTimeout(3000);
await page.screenshot({ path: '/tmp/opencode/shots/t-title.jpg', type: 'jpeg', quality: 74 });
await page.click('#start-btn');
await page.waitForTimeout(800);
await page.keyboard.press('KeyE'); // dismiss intro too
await page.waitForTimeout(1600);

// Try to leave before collecting: door must block.
await page.evaluate(() => { __hollow.teleport(0, 12.9); __hollow.player.yaw = Math.PI; __hollow.player.pitch = 0; });
await page.waitForTimeout(200);
await page.keyboard.down('KeyW');
await page.waitForTimeout(1200);
await page.keyboard.up('KeyW');
console.log('BLOCKED', JSON.stringify(await page.evaluate(() => ({ z: __hollow.player.pos.z, state: __hollow.state, collider: __hollow.world.exit.collider.enabled }))));

// Collect all via legit use while teleported next to each.
for (let i = 0; i < 3; i++) {
  await page.evaluate(() => { const c = __hollow.candles.find(c => !c.taken); __hollow.teleport(c.pos.x + 0.6, c.pos.z); });
  await page.waitForTimeout(300);
  await page.keyboard.press('KeyE');
  await page.waitForTimeout(450);
}
// let the door finish opening
await page.waitForTimeout(2600);
await page.evaluate(() => { __hollow.teleport(0, 12.9); __hollow.player.yaw = Math.PI; __hollow.player.pitch = 0; });
await page.waitForTimeout(300);
await page.keyboard.down('KeyW');
await page.waitForTimeout(1400);
await page.keyboard.up('KeyW');
console.log('CROSS', JSON.stringify(await page.evaluate(() => ({ z: __hollow.player.pos.z, x: __hollow.player.pos.x, state: __hollow.state, openness: __hollow.world.exit.openness, collider: __hollow.world.exit.collider.enabled }))));
await page.waitForTimeout(1200);
console.log('END', JSON.stringify(await page.evaluate(() => ({ state: __hollow.state, visible: !document.getElementById('end-screen').classList.contains('hidden'), title: document.getElementById('end-title').textContent }))));

// verify pause/resume
await page.click('#again-btn');
await page.waitForTimeout(700);
await page.click('#pause-btn');
await page.waitForTimeout(300);
const paused = await page.evaluate(() => ({ state: __hollow.state, visible: !document.getElementById('pause-screen').classList.contains('hidden') }));
await page.click('#resume-btn');
await page.waitForTimeout(300);
const resumed = await page.evaluate(() => ({ state: __hollow.state, hidden: document.getElementById('pause-screen').classList.contains('hidden') }));
console.log('PAUSE', JSON.stringify({ paused, resumed }));
await page.screenshot({ path: '/tmp/opencode/shots/t-final.jpg', type: 'jpeg', quality: 74 });
console.log('ERRORS', JSON.stringify(errors));
await browser.close();

